                            {name}
                        </th>
                    )}
                </tr>
            </thead>
            <tbody>
                {datesArray.map((date) =>
                    <>
                        <tr>
                            <td rowSpan={2}>{date.day} {date.date}</td>
                            <td>
                                <p>
                                    Morning
                                </p>
                            </td>
